function f = HS79_f(x)
f = (x(1) - 1).^2 + (x(1) - x(2)).^2 + (x(2) - x(3)).^2 + (x(3) - x(4)).^4 + (x(4) - x(5)).^4;
end

function g = HS79_g(x)
g = zeros(5, 1);
g(1) = 4*x(1) - 2*x(2) - 2;
g(2) = -2*x(1) + 4*x(2) - 2*x(3);
g(3) = -2*x(2) + 2*x(3) + 4*(x(3) - x(4)).^3;
g(4) = -4*(x(3) - x(4)).^3 + 4*(x(4) - x(5)).^3;
g(5) = -4*(x(4) - x(5)).^3;
end

function c = HS79_c(x)
c = zeros(3, 1);
c(1) = x(1) + x(2).^2 + x(3).^3 - 3*sqrt(2) - 2;
c(2) = x(2) - x(3).^2 + x(4) - 2*sqrt(2) + 2;
c(3) = x(1).*x(5) - 2;
end

function J = HS79_J(x)
J = zeros(3, 5);
J(1, 1) = 1;
